<template><main class="wrap"><el-button text @click="router.push('/products/search')">← 商品一覧に戻る</el-button><el-skeleton v-if="loading" :rows="8" animated/><el-result v-else-if="error" icon="error" title="商品を読み込めません" :sub-title="error"/><el-card v-else class="detail"><el-image :src="product.imageUrl" class="image" fit="contain"><template #error><div class="no-image">商品画像はありません</div></template></el-image><section><el-tag v-if="product.category">{{product.category}}</el-tag><h1>{{product.name}}</h1><p class="price">¥{{money(product.price)}}</p><p>{{product.description||'商品説明はありません'}}</p><el-descriptions :column="1" border><el-descriptions-item label="商品番号">{{product.id}}</el-descriptions-item><el-descriptions-item label="在庫">{{product.stock>0?`在庫あり（${product.stock}点）`:'在庫切れ'}}</el-descriptions-item><el-descriptions-item label="販売状況">{{product.status===1?'販売中':'販売終了'}}</el-descriptions-item></el-descriptions><div class="buy"><el-input-number v-model="quantity" :min="1" :max="product.stock||1" :disabled="!available"/><el-button type="primary" :disabled="!available" :loading="adding" @click="add">カートに入れる</el-button></div></section></el-card></main></template>
<script setup>
import { computed,onMounted,ref,watch } from 'vue';import { ElMessage } from 'element-plus';import { useRoute,useRouter } from 'vue-router';import { getProductById } from '@/api/product';import { addToCart } from '@/api/cart'
const route=useRoute(),router=useRouter(),product=ref(null),loading=ref(false),adding=ref(false),error=ref(''),quantity=ref(1),available=computed(()=>product.value?.status===1&&product.value?.stock>0),money=v=>Number(v).toFixed(2)
const load=async()=>{loading.value=true;error.value='';try{product.value=(await getProductById(route.params.id)).data;quantity.value=1}catch(e){error.value=e.response?.status===404?'商品が見つかりません。':'時間をおいて再度お試しください。'}finally{loading.value=false}};const add=async()=>{adding.value=true;try{await addToCart(product.value.id,quantity.value);ElMessage.success('カートに追加しました')}catch(e){ElMessage.error(e.response?.data?.message||'カートへの追加に失敗しました')}finally{adding.value=false}};watch(()=>route.params.id,load);onMounted(load)
</script><style scoped>.wrap{max-width:1080px;margin:auto;padding:24px}.detail :deep(.el-card__body){display:grid;grid-template-columns:1fr 1fr;gap:36px}.image{height:380px;background:#f4f4f5}.no-image{height:100%;display:grid;place-items:center;color:#909399}.price{font-size:30px;font-weight:700;color:#f56c6c}.buy{display:flex;gap:12px;margin-top:20px}@media(max-width:700px){.detail :deep(.el-card__body){grid-template-columns:1fr}}</style>
